"""J24I22 independent physical-source, hostile and resource research court (Linux)."""
import binascii, hashlib, json, os, pathlib, subprocess, sys, tempfile, unittest, zlib
import physical_relay as pr
import bounded_fd_relay as br
MB=1024*1024

def make_wire(path,payload,codec=0):
    # Independently constructed revision-24 vector (not generated by Builder).
    if codec==0:compressed=payload
    elif codec==1:compressed=br.COMP(payload)
    elif codec==4:
        co=zlib.compressobj(level=6,wbits=-15);compressed=co.compress(payload)+co.flush()
    else:raise ValueError(codec)
    h=hashlib.sha256(payload).digest();crc=binascii.crc32(payload)&0xffffffff
    idx={"v":24,"files":[["blob.bin",0,420,0,len(payload),h,[0,0]]],
         "blobs":[[0,len(payload),len(compressed),codec,0]],
         "recipes":[],"dict_blob":None,
         "fsmeta":{"owner":[0,0],"owner_overrides":[],"xattrs":[]},
         "features":["sha256","dual-index"]}
    raw=br.PACK(idx);enc=br.COMP(raw);ih=br.SHA(raw)
    record=pr.BHDR.pack(pr.BMAGIC,codec,0,0,len(payload),len(compressed),0,crc,h)+compressed
    path.write_bytes(pr.HDR.pack(pr.MAGIC,24,0,len(enc),len(raw),len(record),ih)+enc+record+enc+
        pr.FTR.pack(pr.FMAGIC,0,1,0,0,len(enc),len(raw),0,ih))
    return h.hex()

def court_child(source,dest):
    # /proc/self/clear_refs resets VmHWM (ru_maxrss can inherit fork parent's peak).
    code='import json,os,sys;from bounded_fd_relay import relay;open("/proc/self/clear_refs","w").write("5");b=int(open("/proc/self/status").read().split("VmRSS:")[1].split()[0]);z=relay(sys.argv[1],sys.argv[2]);z["rss_pre_kib"]=b;z["rss_peak_kib"]=int(open("/proc/self/status").read().split("VmHWM:")[1].split()[0]);print(json.dumps(z))'
    env=dict(os.environ,PYTHONPATH=os.pathsep.join(map(str,[pathlib.Path(__file__).parent,pathlib.Path(__file__).parent.parent/"j24i18"])))
    return subprocess.run([sys.executable,"-c",code,str(source),str(dest)],env=env,text=True,capture_output=True,check=True)

class BoundedRelayTests(unittest.TestCase):
    def test_small_exact_checkpoint_and_integrity(self):
        with tempfile.TemporaryDirectory() as td:
            d=pathlib.Path(td)
            for codec in (0,1,4):
                src=d/f"{codec}.cmpct";dst=d/f"{codec}.out"
                make_wire(src,b"J24I22 physical exactness\0"*500,codec)
                receipt=br.relay(src,dst)
                self.assertEqual(src.read_bytes(),dst.read_bytes())
                self.assertEqual(receipt["dead"],0)
                idx,base,_=pr.read_index(dst.read_bytes())
                pr.read_blobs(dst.read_bytes(),idx,base)
                corrupted=d/f"{codec}-corrupt.cmpct";bad=bytearray(src.read_bytes())
                i,b,_=pr.read_index(bytes(bad))
                bad[b+i["blobs"][0][0]+pr.BHDR.size+1]^=1
                corrupted.write_bytes(bad)
                with self.assertRaises(ValueError):br.relay(corrupted,d/f"{codec}-corrupt.out")
                self.assertFalse((d/f"{codec}-corrupt.out").exists())

    def test_hostile_mutation_after_admission_and_symlink_source(self):
        with tempfile.TemporaryDirectory() as td:
            d=pathlib.Path(td);src=d/"src.cmpct";out=d/"out.cmpct"
            make_wire(src,b"SIGNED-SOURCE-"*2000,0)
            data=src.read_bytes();idx,base,_=pr.read_index(data)
            def mutate():
                with open(src,"r+b") as f:
                    f.seek(base+idx["blobs"][0][0]+pr.BHDR.size+4)
                    f.write(b"Q");f.flush();os.fsync(f.fileno())
            with self.assertRaises(ValueError):br.relay(src,out,after_admit=mutate)
            self.assertFalse(out.exists())
            symlink=d/"alias.cmpct";symlink.symlink_to(src)
            with self.assertRaises(OSError):br.relay(symlink,out)
            self.assertFalse(out.exists())
            broken=d/"truncated.cmpct";broken.write_bytes(data[:-1])
            with self.assertRaises(ValueError):br.relay(broken,out)
            self.assertFalse(out.exists())

    def test_large_raw_zstd_deflate_128m_with_bounded_decoder_workspace(self):
        with tempfile.TemporaryDirectory() as td:
            d=pathlib.Path(td)
            shapes=[("raw",64*MB,0,hashlib.shake_256(b"J24I22-64M").digest(64*MB)),
                    ("zstd",128*MB,1,b"\0"*(128*MB)),
                    ("deflate",128*MB,4,b"\0"*(128*MB))]
            for name,length,codec,payload in shapes:
                src=d/f"{name}.cmpct";dst=d/f"{name}.out"
                expected=make_wire(src,payload,codec);del payload
                receipt=json.loads(court_child(src,dst).stdout.strip())
                self.assertEqual(src.stat().st_size,dst.stat().st_size)
                self.assertEqual(br.output_sha(src),br.output_sha(dst))
                self.assertLess(receipt["rss_peak_kib"]-receipt["rss_pre_kib"],48*1024,(name,receipt))
                print("J24I22_LARGE",name,expected,receipt,flush=True)

    def test_real_installed_builder_journal(self):
        from cmpct.builder import Builder
        from cmpct.reader import CMPCT
        from cmpct.transactions import append_update
        with tempfile.TemporaryDirectory() as td:
            d=pathlib.Path(td);root=d/"tree";root.mkdir()
            (root/"original.bin").write_bytes(b"ORIGINAL-"*1024)
            os.link(root/"original.bin",root/"alias.bin")
            src=d/"input.cmpct";dst=d/"relay.cmpct"
            Builder(root,reproducible=True).build(src)
            nextfile=d/"next.bin";nextfile.write_bytes(b"REPLACED-"*1024)
            append_update(src,"original.bin",nextfile)
            receipt=br.relay(src,dst)
            self.assertGreater(receipt["dead"],0)
            self.assertLess(dst.stat().st_size,src.stat().st_size)
            with CMPCT(src) as a,CMPCT(dst) as b:
                self.assertEqual(a.index["fsmeta"],b.index["fsmeta"])
                for row in a.files:
                    other=b.by[row[0]]
                    self.assertEqual(row[:6],other[:6])
                    if row[1]==3:self.assertEqual(row[6],other[6])
                    if row[1]!=1:self.assertEqual(a.read(row[0]),b.read(row[0]))
            source_data=src.read_bytes();dest_data=dst.read_bytes()
            old_index,oldbase,_=pr.read_index(source_data)
            new_index,newbase,depth=pr.read_index(dest_data)
            pr.read_blobs(source_data,old_index,oldbase)
            pr.read_blobs(dest_data,new_index,newbase)
            self.assertEqual(depth,0)
            print("J24I22_REAL_BUILDER",receipt,flush=True)

if __name__=="__main__":unittest.main()
